import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.vLhlLNVn.js";const a="/assets/einstellungen-geraete.CMjpdoYt.png",s="/assets/geraet-hinzufuegen.DITgNzXz.png",d="/assets/geraet-hinzufuegen-fehler.D0IaUEkY.png",l="/assets/geraet-bearbeiten.lpiZTwCQ.png",k=JSON.parse('{"title":"Das erste Gerät einrichten","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/01.erste-schritte/02.erstes-geraet.md"},"headers":[],"relativePath":"de/adapter/wled/erste-schritte/erstes-geraet.md","filePath":"de/adapter/wled/erste-schritte/erstes-geraet.md","lastUpdated":null}'),o={name:"de/adapter/wled/erste-schritte/erstes-geraet.md"};function h(u,e,c,g,m,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="das-erste-gerat-einrichten" tabindex="-1">Das erste Gerät einrichten <a class="header-anchor" href="#das-erste-gerat-einrichten" aria-label="Permalink to &quot;Das erste Gerät einrichten&quot;">​</a></h1><p><a id="adapter-wled-devices-automatically"></a></p><h2 id="wie-und-wann-findet-der-adapter-meine-wled-gerate-automatisch" tabindex="-1">Wie und wann findet der Adapter meine WLED-Geräte automatisch? <a class="header-anchor" href="#wie-und-wann-findet-der-adapter-meine-wled-gerate-automatisch" aria-label="Permalink to &quot;Wie und wann findet der Adapter meine WLED-Geräte automatisch?&quot;">​</a></h2><p><strong>Kurz:</strong> Der Adapter sucht beim Start der Instanz einmal per Bonjour (mDNS) nach WLED-Geräten. Vorher verbindet er sich mit allen Geräten, die er schon kennt, über ihre gespeicherte IP-Adresse. Einen regelmäßigen Suchlauf gibt es nicht. Fehlt ein Gerät, startest du die Suche von Hand neu oder fügst es per IP-Adresse hinzu.</p><h3 id="was-beim-start-passiert" tabindex="-1">Was beim Start passiert <a class="header-anchor" href="#was-beim-start-passiert" aria-label="Permalink to &quot;Was beim Start passiert&quot;">​</a></h3><ol><li>Der Adapter liest alle Geräte, die unter <code>wled.&lt;Instanz&gt;</code> schon angelegt sind, und verbindet sich mit jedem über die gespeicherte IP-Adresse. Im Log steht <code>Try to contact &lt;Anzahl&gt; known devices</code>.</li><li>Danach startet er die Bonjour-Suche nach dem Dienst <code>wled</code>. Im Log steht <code>Bonjour service started, new devices will be detected automatically</code>.</li><li>Jedes Gerät, das sich meldet und das der Adapter noch nicht kennt, legt er an. Im Log steht <code>New WLED device found &lt;Name&gt; on IP 192.168.x.y</code>. Das Geräteobjekt heißt nach der MAC-Adresse des Geräts.</li></ol><p>Die Suche bleibt danach geöffnet, bis die Instanz stoppt. Meldet sich ein Gerät später von selbst im Netz, etwa nach dem Einschalten, kann der Adapter es dadurch auch dann noch aufnehmen. Darauf verlassen solltest du dich nicht: Aktiv fragt der Adapter nur beim Start und bei einer Suche von Hand.</p><h3 id="was-die-suche-braucht" tabindex="-1">Was die Suche braucht <a class="header-anchor" href="#was-die-suche-braucht" aria-label="Permalink to &quot;Was die Suche braucht&quot;">​</a></h3><ul><li><strong>mDNS ist in WLED eingeschaltet.</strong> In WLED unter „WiFi Setup“ steht im Feld „mDNS address“ ein Name. Ist das Feld leer, meldet sich das Gerät nicht per Bonjour.</li><li><strong>Gleiches Netz.</strong> ioBroker und WLED liegen im selben Netz, und Multicast kommt durch. In Netzen mit VLAN-Trennung oder mit getrenntem Gäste-WLAN findet die Suche das Gerät meist nicht.</li><li><strong>Das Gerät läuft.</strong> Ein ausgeschaltetes Gerät meldet sich nicht.</li></ul><h3 id="wenn-ein-gerat-fehlt" tabindex="-1">Wenn ein Gerät fehlt <a class="header-anchor" href="#wenn-ein-gerat-fehlt" aria-label="Permalink to &quot;Wenn ein Gerät fehlt&quot;">​</a></h3><ol><li>Prüfe, ob du die WLED-Oberfläche unter <code>http://192.168.x.y</code> vom selben Netz aus öffnen kannst.</li><li>Starte die Suche neu: im Admin im „Konfig-Manager“ (in älteren Admin-Versionen „Geräte“) bei der Instanz <code>wled.&lt;Instanz&gt;</code> über „Neue Geräte suchen“. Das Ergebnis siehst du nach einigen Sekunden in der Liste. Ein Neustart der Instanz löst dieselbe Suche aus.</li><li>Findet die Suche das Gerät nicht, füge es per IP-Adresse hinzu.</li></ol><p><strong>Bis v0.9.2:</strong> Geräte, die erst nach dem Start dazukommen, über die laufende Suche, „Neue Geräte suchen“ oder per IP-Adresse, überwacht der Adapter nicht. Fällt so ein Gerät aus, verbindet es sich bis zum nächsten Neustart der Instanz nicht neu. Starte die Instanz deshalb neu, wenn ein neu gefundenes Gerät nicht mehr reagiert.</p><p><strong>Ab v0.9.3:</strong> Auch später gefundene Geräte werden überwacht und verbinden sich nach einem Ausfall von selbst neu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/901" target="_blank" rel="noreferrer">#901</a>). „Neue Geräte suchen“ beendet zuerst die laufende Suche und startet dann eine neue (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/905" target="_blank" rel="noreferrer">#905</a>).</p><p><strong>Ab v0.10.0:</strong> Die automatische Suche beim Start lässt sich abschalten, in den Instanzeinstellungen im Reiter „Einstellungen“, Bereich „Erkennung“, mit dem Haken „Geräte automatisch per Bonjour/mDNS suchen“. Ist sie aus, nutzt der Adapter nur die bekannten und die per IP-Adresse hinzugefügten Geräte. Im Log steht dann <code>Automatic discovery (Bonjour/mDNS) is switched off, only known and manually added devices are used</code>. Die Suche von Hand funktioniert weiterhin (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/897" target="_blank" rel="noreferrer">#897</a>).</p><p><strong>Ab v0.10.0:</strong> In den Instanzeinstellungen gibt es im Reiter „Geräte“ zusätzlich den Knopf „Geräte suchen“. Er sucht einige Sekunden lang und meldet dann „Neue Geräte gefunden: &lt;Anzahl&gt;“ oder „Keine neuen Geräte gefunden.“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><p><img src="'+a+'" alt="Reiter „Geräte“ in den Instanzeinstellungen mit der Geräteliste und den Knöpfen „Geräte suchen“ und „Gerät hinzufügen“"></p><p><strong>Ab v0.10.0:</strong> Steht zwischen ioBroker und WLED ein mDNS-Relay, etwa zwischen zwei VLANs, übernimmt der Adapter die IP-Adresse, die das Gerät selbst meldet, und nicht mehr die Adresse des Relays (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/897" target="_blank" rel="noreferrer">#897</a>).</p><p><strong>Siehe auch:</strong> <a href="#add-device-manually-ip-if">Wie füge ich ein Gerät manuell per IP hinzu?</a> · <a href="./../referenz/instanz-einstellungen#polling-interval-auto-discovery">Wo stelle ich Polling-Intervall und Auto-Erkennung ein?</a> · <a href="./../anleitungen/geraete-verwalten#remove-wled-device-adapter">Warum taucht ein gelöschtes Gerät wieder auf?</a></p><p><a id="add-device-manually-ip-if"></a></p><h2 id="wie-fuge-ich-ein-gerat-manuell-per-ip-hinzu-und-was-tue-ich-wenn-es-trotzdem-nicht-erscheint" tabindex="-1">Wie füge ich ein Gerät manuell per IP hinzu, und was tue ich, wenn es trotzdem nicht erscheint? <a class="header-anchor" href="#wie-fuge-ich-ein-gerat-manuell-per-ip-hinzu-und-was-tue-ich-wenn-es-trotzdem-nicht-erscheint" aria-label="Permalink to &quot;Wie füge ich ein Gerät manuell per IP hinzu, und was tue ich, wenn es trotzdem nicht erscheint?&quot;">​</a></h2><p><strong>Kurz:</strong> Du trägst die IP-Adresse des Geräts in den Instanzeinstellungen über „Gerät hinzufügen“ ein oder im „Konfig-Manager“ (in älteren Admin-Versionen „Geräte“) über „Neues Gerät zu WLED hinzufügen“. Der Adapter liest das Gerät sofort ein und legt es an. Steht es danach nicht in der Liste, war das Gerät unter dieser Adresse nicht erreichbar, es läuft keine WLED-Firmware darauf, oder die Liste ist noch nicht neu geladen.</p><p>Du brauchst das vor allem, wenn die automatische Suche das Gerät nicht findet, zum Beispiel in Netzen mit VLAN-Trennung.</p><h3 id="so-gehst-du-vor-in-den-instanzeinstellungen" tabindex="-1">So gehst du vor: in den Instanzeinstellungen <a class="header-anchor" href="#so-gehst-du-vor-in-den-instanzeinstellungen" aria-label="Permalink to &quot;So gehst du vor: in den Instanzeinstellungen&quot;">​</a></h3><p><strong>Bis v0.9.3:</strong> So sieht es in den alten Instanzeinstellungen aus. Für v0.10.0 siehe weiter unten.</p><ol><li>Öffne im Admin unter „Instanzen“ die Einstellungen von <code>wled.&lt;Instanz&gt;</code>.</li><li>Klicke auf „Gerät hinzufügen“.</li><li>Trage im Dialog „Gerät manuell hinzufügen“ im Feld „IP“ die Adresse ein, zum Beispiel <code>192.168.x.y</code>, und klicke auf „Hinzufügen“.</li><li>Hat es geklappt, lädt die Gerätetabelle neu und zeigt das Gerät mit seinem Namen aus WLED. Hat es nicht geklappt, erscheint „Das Hinzufügen des Geräts ist fehlgeschlagen. Geben Sie die richtige IP ein und stellen Sie sicher, dass das Gerät erreichbar ist“.</li></ol><h3 id="so-gehst-du-vor-im-konfig-manager" tabindex="-1">So gehst du vor: im Konfig-Manager <a class="header-anchor" href="#so-gehst-du-vor-im-konfig-manager" aria-label="Permalink to &quot;So gehst du vor: im Konfig-Manager&quot;">​</a></h3><ol><li>Öffne im Admin den „Konfig-Manager“ (in älteren Admin-Versionen „Geräte“) und wähle die Instanz <code>wled.&lt;Instanz&gt;</code>.</li><li>Klicke auf „Neues Gerät zu WLED hinzufügen“.</li><li>Trage im Dialog „Neues Gerät hinzufügen“ im Feld „IP-Adresse“ die Adresse ein und bestätige.</li><li>Die Liste lädt neu. Ist die Adresse kein gültiges Format, erscheint „IP-Adresse &lt;Adresse&gt; ist ungültig“.</li></ol><h3 id="per-skript" tabindex="-1">Per Skript <a class="header-anchor" href="#per-skript" aria-label="Permalink to &quot;Per Skript&quot;">​</a></h3><p>Mit <code>sendTo</code> fügst du ein Gerät aus einem Skript hinzu. Die Antwort ist <code>success</code> oder <code>failed</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;addDevice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;192.168.x.y&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Gerät hinzufügen: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><h3 id="wenn-das-gerat-danach-nicht-in-der-liste-steht" tabindex="-1">Wenn das Gerät danach nicht in der Liste steht <a class="header-anchor" href="#wenn-das-gerat-danach-nicht-in-der-liste-steht" aria-label="Permalink to &quot;Wenn das Gerät danach nicht in der Liste steht&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ursache</th><th>Woran du es erkennst</th><th>Was du tust</th></tr></thead><tbody><tr><td>Das Gerät ist unter der Adresse nicht erreichbar, ausgeschaltet oder in einem anderen Netz.</td><td>Die WLED-Oberfläche unter <code>http://192.168.x.y</code> öffnet sich vom ioBroker-Netz aus nicht. Der Adapter wartet höchstens 3 Sekunden auf eine Antwort.</td><td>Prüfe Adresse, Stromversorgung und WLAN des Geräts und versuche es erneut.</td></tr><tr><td>Auf dem Gerät läuft keine WLED-Firmware.</td><td>Unter <code>http://192.168.x.y/json/info</code> kommt kein WLED-JSON zurück.</td><td>Siehe <a href="./installation#magic-home-ready-made-wled">Funktionieren Magic Home und fertige WLED-Controller mit dem Adapter?</a></td></tr><tr><td>Das Gerät ist schon angelegt und verbunden.</td><td>Die Antwort ist <code>failed</code>, obwohl das Gerät läuft. Es steht schon in der Liste, unter seinem Namen aus WLED.</td><td>Nichts, das Gerät ist schon da.</td></tr><tr><td>Die Liste ist nicht aktuell.</td><td>Das Gerät erscheint erst, wenn der Adapter es vollständig eingelesen hat. Die Anzeige „In Verbindung gebracht“ liest die Tabelle nur beim Öffnen der Einstellungen.</td><td>Schließe die Instanzeinstellungen und öffne sie erneut.</td></tr></tbody></table><p><strong>Bis v0.9.2:</strong> Ein Gerät, das du nach dem Start der Instanz hinzufügst, überwacht der Adapter nicht. Fällt es aus, verbindet es sich bis zum nächsten Neustart der Instanz nicht neu. Starte die Instanz nach dem Hinzufügen einmal neu. Im Konfig-Manager erscheint außerdem keine Meldung, wenn das Gerät nicht antwortet.</p><p><strong>Ab v0.9.3:</strong> Auch nachträglich hinzugefügte Geräte werden überwacht (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/901" target="_blank" rel="noreferrer">#901</a>). Im Konfig-Manager meldet der Dialog „Gerät &lt;Adresse&gt; antwortet nicht. Bitte prüfe die IP-Adresse und ob das Gerät eingeschaltet ist.“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/916" target="_blank" rel="noreferrer">#916</a>) oder „Gerät &lt;Adresse&gt; ist bereits hinzugefügt“. Adressen mit Zahlen über 255 lehnt er als ungültig ab (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/915" target="_blank" rel="noreferrer">#915</a>).</p><p><strong>Ab v0.10.0:</strong> Die Instanzeinstellungen sind neu aufgebaut. Im Reiter „Geräte“ der Einstellungen klickst du auf „Gerät hinzufügen“ und trägst im Dialog „Gerät per IP hinzufügen“ im Feld „IP-Adresse oder Hostname“ die Adresse oder den Hostnamen des Geräts ein. Der Dialog meldet „&lt;Gerät&gt; wurde hinzugefügt.“ oder sagt, was nicht stimmt: „Unter &lt;Adresse&gt; antwortet kein WLED-Gerät. Prüfe die Adresse und ob das Gerät eingeschaltet und im Netz ist.“, „&lt;Adresse&gt; ist bereits als Gerät vorhanden.“ oder „Das ist keine gültige IP-Adresse und kein gültiger Hostname.“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/266" target="_blank" rel="noreferrer">#266</a>).</p><p><img src="'+s+'" alt="Dialog „Gerät per IP hinzufügen“ mit dem Feld „IP-Adresse oder Hostname“"></p><p><img src="'+d+'" alt="Meldung im Dialog, wenn unter der Adresse kein WLED-Gerät antwortet"></p><p><strong>Siehe auch:</strong> <a href="#adapter-wled-devices-automatically">Wie und wann findet der Adapter meine WLED-Geräte automatisch?</a> · <a href="./../anleitungen/geraete-verwalten#remove-wled-device-adapter">Wie entferne ich ein WLED-Gerät aus dem Adapter?</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist?</a></p><p><a id="device-show-only-wled-mac"></a></p><h2 id="warum-zeigt-mein-gerat-nur-wled-oder-die-mac-adresse-als-namen-und-kann-ich-es-umbenennen" tabindex="-1">Warum zeigt mein Gerät nur &quot;WLED&quot; oder die MAC-Adresse als Namen, und kann ich es umbenennen? <a class="header-anchor" href="#warum-zeigt-mein-gerat-nur-wled-oder-die-mac-adresse-als-namen-und-kann-ich-es-umbenennen" aria-label="Permalink to &quot;Warum zeigt mein Gerät nur &quot;WLED&quot; oder die MAC-Adresse als Namen, und kann ich es umbenennen?&quot;">​</a></h2><p><strong>Kurz:</strong> Den Namen übernimmt der Adapter aus WLED. Hast du in WLED keinen eigenen Namen vergeben, heißt das Gerät „WLED“. Die MAC-Adresse ist die ID des Geräts im Objektbaum, zum Beispiel <code>wled.0.&lt;MAC&gt;</code>, und ändert sich nie. Den Namen änderst du am besten in WLED selbst. Einen Namen, den du nur in ioBroker änderst, überschreibt der Adapter in v0.9.2 beim nächsten Neustart wieder.</p><h3 id="woher-name-und-id-kommen" tabindex="-1">Woher Name und ID kommen <a class="header-anchor" href="#woher-name-und-id-kommen" aria-label="Permalink to &quot;Woher Name und ID kommen&quot;">​</a></h3><ul><li><strong>ID:</strong> Das Geräteobjekt heißt nach der MAC-Adresse, die WLED meldet, zum Beispiel <code>wled.0.&lt;MAC&gt;</code>. Alle Datenpunkte liegen darunter. Die ID bleibt gleich, auch wenn sich Name oder IP-Adresse ändern.</li><li><strong>Name:</strong> Als Namen des Geräteobjekts setzt der Adapter den Namen, den WLED meldet. Ab Werk ist das „WLED“. Bei mehreren Geräten ohne eigenen Namen heißen deshalb alle gleich, und du unterscheidest sie nur an der MAC-Adresse.</li></ul><h3 id="so-gibst-du-dem-gerat-in-wled-einen-namen" tabindex="-1">So gibst du dem Gerät in WLED einen Namen <a class="header-anchor" href="#so-gibst-du-dem-gerat-in-wled-einen-namen" aria-label="Permalink to &quot;So gibst du dem Gerät in WLED einen Namen&quot;">​</a></h3><ol><li>Öffne die WLED-Oberfläche unter <code>http://192.168.x.y</code>.</li><li>Geh auf „Config“ und dann auf „User Interface“.</li><li>Trag im Feld „Server description“ den Namen ein, zum Beispiel <code>Küche Theke</code>, und speichere.</li><li>Starte die Instanz <code>wled.&lt;Instanz&gt;</code> neu. Der Adapter liest das Gerät dabei neu ein und übernimmt den Namen.</li></ol><h3 id="umbenennen-in-iobroker" tabindex="-1">Umbenennen in ioBroker <a class="header-anchor" href="#umbenennen-in-iobroker" aria-label="Permalink to &quot;Umbenennen in ioBroker&quot;">​</a></h3><p><strong>Bis v0.9.3:</strong> Im „Konfig-Manager“ (in älteren Admin-Versionen „Geräte“) benennst du ein Gerät über „Gerät umbenennen“ um. Das ändert nur den Namen des Geräteobjekts in ioBroker, nicht den Namen in WLED.</p><p><strong>Bis v0.9.2:</strong> Jedes Mal, wenn der Adapter das Gerät neu einliest, setzt er wieder den Namen aus WLED. Das passiert bei jedem Start der Instanz und nach jedem Wiederverbinden. Ein Name, den du nur in ioBroker vergeben hast, geht dabei verloren. Vergib den Namen deshalb in WLED.</p><p><strong>Ab v0.9.3:</strong> Einen Namen, den du in ioBroker geändert hast, behält der Adapter. Er setzt den Namen aus WLED nur noch, solange der Name in ioBroker dem zuletzt übernommenen WLED-Namen entspricht. Benennst du das Gerät später in WLED um, folgt der Name in ioBroker also nur, wenn du ihn dort nicht geändert hast. Einen Namen, den du vor dem Update geändert hast, überschreibt der Adapter beim ersten Start mit v0.9.3 noch einmal, weil er den letzten WLED-Namen erst ab dieser Version speichert.</p><p><strong>Ab v0.10.0:</strong> „Gerät umbenennen“ heißt im Konfig-Manager „Gerät bearbeiten“. Im Dialog änderst du den Namen im Feld „Name in ioBroker“. Mit dem Haken „Name von WLED übernehmen (&lt;WLED-Name&gt;)“ holst du den Namen aus WLED zurück. Danach folgt der Name in ioBroker wieder jeder Umbenennung in WLED (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/927" target="_blank" rel="noreferrer">#927</a>).</p><p><img src="'+l+'" alt="Dialog „Gerät bearbeiten“ im Konfig-Manager mit „Name in ioBroker“, „Name von WLED übernehmen“ und „Kurz aufeinander folgende Befehle bündeln“"></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Das gilt nur für den Namen des Geräts. Die Namen der Datenpunkte darunter, etwa <code>bri</code> oder <code>seg.0.col.0</code>, setzt der Adapter bei jedem Start aus seiner eigenen Liste zurück. Eigene Namen für einzelne Datenpunkte vergibst du über einen Alias.</p></div><p><strong>Siehe auch:</strong> <a href="#adapter-wled-devices-automatically">Wie und wann findet der Adapter meine WLED-Geräte automatisch?</a> · <a href="./../anleitungen/vis-und-smarthome#connect-wled-iot-adapter-switch">Wie verbinde ich WLED mit dem iot-Adapter?</a></p>',53)])])}const f=n(o,[["render",h]]);export{k as __pageData,f as default};
